<?php use App\Helpers\View;?><div class="admin-head"><div><span class="eyebrow">ANÁLISIS</span><h1>Reportes</h1></div><a href="/admin">← Panel</a></div><div class="two-col"><section class="panel"><h2>Ventas por día</h2><?php foreach($daily as $d):?><div class="orderrow"><span><b><?=date('d/m/Y',strtotime($d['day']))?></b><small><?=$d['orders_count']?> pedidos</small></span><strong>$<?=number_format($d['sales'],2)?></strong></div><?php endforeach;?></section><section class="panel"><h2>Productos más vendidos</h2><?php foreach($top as $t):?><div class="orderrow"><span><b><?=View::e($t['product_name'])?></b><small><?=$t['units']?> unidades</small></span><strong>$<?=number_format($t['revenue'],2)?></strong></div><?php endforeach;?></section></div>
